    f
}

fn quote(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if c < ' ' => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

fn pack(ids: &[usize], cells: &[String]) -> String {
    let parts: Vec<String> = ids.iter().filter_map(|&i| cells.get(i)).map(|s| quote(s)).collect();
    format!("[{}]", parts.join(","))
}

