use std::collections::HashSet;
use std::fs;

const RIM: &str = include_str!("../foldrib/rim.rs");
const POOL: &str = include_str!("../internpit/pool.rs");
const INK: &str = include_str!("../restcue/ink.rs");
const HEARTH: &str = include_str!("hearth.rs");
const BOOT: &str = include_str!("../steerpit/boot.rs");

pub fn rib_d() -> i32 {
    let entries = match fs::read_dir("/app/daycards") { Ok(v) => v, Err(_) => return 1 };
    let mut cards = Vec::new();
    for entry in entries {
        let Ok(entry) = entry else { return 1 };
        let path = entry.path();
        if path.is_file() {
            let Ok(text) = fs::read_to_string(&path) else { return 1 };
            cards.push(text);
        }
    }
    if cards.is_empty() { return 1; }
    let freeze = cards.iter().any(|s| s.lines().any(|l| l.trim() == "emit freeze"));
    let cells = cards.iter().any(|s| s.lines().any(|l| l.trim() == "emit cells"));
    if !freeze || !cells { return 1; }

    let tree = match fs::read_to_string("/app/vatslip/TREE.txt") { Ok(v) => v, Err(_) => return 1 };
    let names: HashSet<&str> = tree.lines().map(str::trim).filter(|s| !s.is_empty()).collect();
    let pieces = [
        ("foldrib", "/app/foldrib/rim.rs", RIM),
        ("internpit", "/app/internpit/pool.rs", POOL),
        ("restcue", "/app/restcue/ink.rs", INK),
        ("emitbay", "/app/emitbay/hearth.rs", HEARTH),
        ("steerpit", "/app/steerpit/boot.rs", BOOT),
